<?php
namespace App\Models\FbMarketing;
use Illuminate\Database\Eloquent\Model;
class FbmCampaign extends Model{protected $table='fbm_campaigns';protected $guarded=[];protected $casts=['is_available'=>'boolean','last_seen_at'=>'datetime','provider_created_time'=>'datetime','provider_updated_time'=>'datetime'];protected $hidden=['provider_sync_key'];public function connection(){return $this->belongsTo(FbmConnection::class,'fbm_connection_id');}public function adAccount(){return $this->belongsTo(FbmAdAccount::class,'fbm_ad_account_id');}public function toSafeSummary():array{return ['id'=>(int)$this->id,'fbm_connection_id'=>(int)$this->fbm_connection_id,'fbm_ad_account_id'=>(int)$this->fbm_ad_account_id,'connection_name'=>optional($this->connection)->connection_name,'ad_account_name'=>optional($this->adAccount)->asset_name,'name'=>$this->name,'objective'=>$this->objective,'configured_status'=>$this->configured_status,'effective_status'=>$this->effective_status,'is_available'=>(bool)$this->is_available,'last_seen_at'=>optional($this->last_seen_at)->toDateTimeString(),'created_at'=>optional($this->created_at)->toDateTimeString(),'updated_at'=>optional($this->updated_at)->toDateTimeString()];}}
